package com.bank.resilience.containment;

import java.util.concurrent.*;

// Isolates a dependency's capacity so it cannot starve the whole service.
public class Bulkhead {
    private final Semaphore permits;
    private final ExecutorService isolated;
    public Bulkhead(int maxConcurrent) {
        this.permits = new Semaphore(maxConcurrent);
        this.isolated = Executors.newFixedThreadPool(maxConcurrent);
    }
    // Runs a call with bounded concurrency and a deadline; frees the slot fast.
    public <T> T call(Callable<T> task, long deadlineMs, T degradeValue) {
        if (!permits.tryAcquire()) return degradeValue; // shed when bulkhead full
        try {
            Future<T> f = isolated.submit(task);
            return f.get(deadlineMs, TimeUnit.MILLISECONDS); // deadline → free thread
        } catch (TimeoutException | ExecutionException | InterruptedException e) {
            return degradeValue; // graceful degradation
        } finally {
            permits.release();
        }
    }
    public void shutdown() { isolated.shutdownNow(); }
}
