package com.bank.resilience.containment;

import java.util.concurrent.atomic.AtomicLong;

// Caps retries to a fraction of total requests to prevent retry storms.
public class RetryBudget {
    private final double maxFraction;
    private final AtomicLong total = new AtomicLong();
    private final AtomicLong retries = new AtomicLong();
    public RetryBudget(double maxFraction) { this.maxFraction = maxFraction; }
    public void recordRequest() { total.incrementAndGet(); }
    public boolean tryRetry() {
        long t = total.get();
            if (retries.get() < t * maxFraction) { retries.incrementAndGet();
            return true; }
        return false; // budget exhausted → do NOT retry during broad outage
    }
    public long retries() { return retries.get(); }
}
