package com.bank.resilience.service;

import com.bank.resilience.containment.Bulkhead;
import com.bank.resilience.containment.RetryBudget;
import com.bank.resilience.dep.FraudCheckClient;
import java.util.logging.Logger;

public class TransferService {
    private static final Logger log = Logger.getLogger(TransferService.class.getName());
    private final FraudCheckClient fraud;
    private final Bulkhead fraudBulkhead;   // isolated so it can't starve balance lookups
    private final RetryBudget retryBudget;
    private final long deadlineMs;

    public TransferService(FraudCheckClient fraud, Bulkhead fraudBulkhead,
                           RetryBudget retryBudget, long deadlineMs) {
            this.fraud = fraud;
            this.fraudBulkhead = fraudBulkhead;
            this.retryBudget = retryBudget;
            this.deadlineMs = deadlineMs;
    }

    public String transfer(String from, String to, String amount) {
        retryBudget.recordRequest();
        // Fraud check via bulkhead + deadline; degrade to CONSERVATIVE if slow/unavailable.
        String verdict = fraudBulkhead.call(
                () -> fraud.check(from, to, amount), deadlineMs, "CONSERVATIVE");
        if ("CONSERVATIVE".equals(verdict)) {
            log.warning(() -> "Fraud-check degraded; applying conservative decision for " + from);
            // Conservative: allow small amounts, hold large ones for async review.
            return Double.parseDouble(amount) <= 50000 ? "APPROVED_DEGRADED" : "HELD_FOR_REVIEW";
        }
        return "APPROVED".equals(verdict) ? "COMPLETED" : "REJECTED";
    }
}
