package com.bank.resilience.service;

import java.util.logging.Logger;

// Independent feature. Must stay healthy even when fraud-check is slow.
public class BalanceService {
    private static final Logger log = Logger.getLogger(BalanceService.class.getName());
    public String getBalance(String accountId) {
        // Fast local read — should NEVER be blocked by fraud-check slowness.
        log.fine(() -> "Balance read for " + accountId);
        return accountId.equals("SAV2001") ? "1000000" : "250000";
    }
}
