package com.bank.resilience;

import com.bank.resilience.containment.Bulkhead;
import com.bank.resilience.containment.RetryBudget;
import com.bank.resilience.dep.FraudCheckClient;
import com.bank.resilience.service.BalanceService;
import com.bank.resilience.service.TransferService;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;
import java.util.logging.*;

public class CascadeDemo {
    private static final Logger log = Logger.getLogger(CascadeDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h); log.setLevel(Level.INFO);
    }
    public static void main(String[] args) throws Exception {
        FraudCheckClient slowFraud = new FraudCheckClient(1000); // 1s slow dependency
        Bulkhead fraudBulkhead = new Bulkhead(4);   // isolate fraud capacity
        RetryBudget budget = new RetryBudget(0.1);
        TransferService transfers = new TransferService(slowFraud, fraudBulkhead, budget, 100);
        BalanceService balances = new BalanceService();

        ExecutorService pool = Executors.newFixedThreadPool(50);
        AtomicLong balanceOk = new AtomicLong();

        // 40 slow transfers + 40 balance reads concurrently.
        for (int i = 0; i < 40; i++) {
            pool.submit(() -> transfers.transfer("SAV2001", "CUR3001", "100000"));
            pool.submit(() -> { balances.getBalance("SAV2001"); balanceOk.incrementAndGet(); });
        }
        pool.shutdown();
        pool.awaitTermination(10, TimeUnit.SECONDS);

        // CONTAINED: balance reads unaffected because fraud-check is bulkheaded.
        log.info(() -> "Balance reads succeeded=" + balanceOk.get() + "/40 (unaffected by slow fraud)");
        log.info(() -> "Retries used=" + budget.retries() + " (capped by budget)");
        log.info("Transfers degraded gracefully (HELD_FOR_REVIEW) instead of hanging");
        fraudBulkhead.shutdown();
    }
}

